def retry_with_backoff(func, attempts=3, base_delay=1.0, backoff_factor=2.0, *args, **kwargs):
    import time

    delay = base_delay
    last_exc = None
    for attempt in range(attempts):
        try:
            return func(*args, **kwargs)
        except Exception as exc:
            last_exc = exc
            if attempt + 1 < attempts:
                time.sleep(delay)
                delay *= backoff_factor
    raise last_exc

